import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long[] p = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) sum += p[i] = nextLong();
        // Every element is counted n-1 times in sum(pref).
        long total = sum / (n - 1);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(total - p[i]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	p := make([]int64, n)
	var sum int64
	for i := range p {
		fmt.Fscan(in, &p[i])
		sum += p[i]
	}
	// Every element is counted n-1 times in sum(pref).
	total := sum / int64(n-1)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i, v := range p {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(total-v, 10))
	}
	w.WriteByte('\n')
}
